import js from '@eslint/js';
import tseslint from 'typescript-eslint';
import oxlint from 'eslint-plugin-oxlint';

// oxlint runs first (`.oxlintrc.json`, RFC 0002 §6.5); ESLint keeps what
// oxlint cannot read, and `eslint-plugin-oxlint`, last, turns off every rule
// oxlint already covers. Shape generated by create-vue 3.24.
export default [
  js.configs.recommended,
  ...tseslint.configs.recommended,
  {
    ignores: [
      '**/dist',
      '**/out-tsc',
      '**/vite.config.*.timestamp*',
      '**/playwright-report',
      '**/test-results',
      'docs/**',
    ],
  },
  {
    // oxlint owns unused variables (`.oxlintrc.json`, `_` prefix ignored).
    rules: { '@typescript-eslint/no-unused-vars': 'off' },
  },
  {
    // TypeScript (vue-tsc) already checks identifiers; no-undef does not know
    // the DOM globals here (typescript-eslint turns it off the same way).
    files: ['**/*.vue'],
    rules: { 'no-undef': 'off' },
  },
  {
    // libs/front/front-api is generated by @hey-api/openapi-ts.
    files: ['libs/front/front-api/**/*.ts'],
    // The generator's own eslint-disable comments target rules oxlint now
    // owns; they are not ours to remove.
    linterOptions: { reportUnusedDisableDirectives: 'off' },
    rules: {
      '@typescript-eslint/ban-ts-comment': 0,
      '@typescript-eslint/no-non-null-assertion': 0,
      '@typescript-eslint/no-explicit-any': 0,
      '@typescript-eslint/no-empty-interface': 0,
      '@typescript-eslint/no-inferrable-types': 0,
    },
  },
  ...oxlint.buildFromOxlintConfigFile(`${import.meta.dirname}/.oxlintrc.json`),
];
